(async()=>{'use strict';const $=s=>document.querySelector(s),names=['Яркая орбита','Бортовая карта','Пояс запуска'];
const [final,marker,author,extra]=await Promise.all(['final.json','../marker/final-selection.json','scenes.json','additional-scenes.json'].map(async p=>(await fetch(p,{cache:'no-store'})).json()));const scenes=[...author,...extra];let native=false,selected=0,scene=0;
const draw=(c,s)=>SpaceFoxCR.render(c,s,marker.candidates[0]);
function card(face,label){const a=document.createElement('article');a.className='card';const h=document.createElement('h2');h.textContent=label;const v=document.createElement('div');v.className='preview';v.append(face);a.append(h,v);return a;}
function old(c){const m=marker.candidates.find(m=>m.id===c.reference);return $('#oldSource').value==='previous'?SpaceFoxM.controls().find(p=>p.base.id===m.base.id):m;}
function paint(){const s=scenes[scene];document.body.className=native?'native':'overview';$('#gallery').replaceChildren();const chosen=native?[final[selected]]:final;for(const c of chosen){const prior=old(c);$('#gallery').append(card(SpaceFoxMR.render(prior,s),'Прошлый · '+(prior.control?SpaceFoxMarkerData.names[prior.base.id]:marker.names[marker.candidates.findIndex(m=>m.id===prior.id)])));}for(const c of chosen)$('#gallery').append(card(draw(c,s),'Новый · '+names[final.findIndex(k=>k.id===c.id)]+' · '+c.id));$('#status').textContent=(native?'Пара390×390':'Верхний ряд — прошлый, нижний — новый · 222×222')+' · одинаковые данные и масштаб.';}
$('#scene').replaceChildren(...scenes.map((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=s.id;return o;}));$('#family').replaceChildren(...names.map((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=s;return o;}));$('#scene').onchange=()=>{scene=+$('#scene').value;paint();};$('#family').onchange=()=>{selected=+$('#family').value;native=true;paint();};$('#oldSource').onchange=paint;$('#size').onclick=()=>{native=!native;paint();};await Promise.all(["600 80px 'Roboto Condensed'","600 80px 'Barlow Condensed'","600 80px 'Saira Condensed'","500 21px 'Noto Sans'"].map(f=>document.fonts.load(f,'Россия USA')));await document.fonts.ready;paint();})();
